import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen0Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // length 7, buffer[7] is out of bounds? 
        // Wait, looking at the code: trailer = buffer[end / 1]; 
        // If end = offset + length, and end = 7, buffer[7] would throw IndexOutOfBounds.
        // However, the buffer provided must be large enough.
        byte[] buf = new byte[8];
        System.arraycopy("000123 ".getBytes(), 0, buf, 0, 7);
        long result = TarUtils.parseOctal(buf, 0, 7);
        assertEquals(83, result); // 123 octal = 83 decimal
    }


















}

