package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen0Test {





    @Test
    public void testParseOctal_LeadingSpaces() {
        byte[] buffer = "   012 ".getBytes();
        byte[] buf = new byte[10];
        System.arraycopy(buffer, 0, buf, 0, 7);
        // end = 7. buffer[7] is 0. trailer = buffer[7] (0). end-- (6).
        // trailer = buffer[5] (' '). end-- (5).
        // start = 3 ('0'). end = 5. Loop '0', '1', '2'? No, end is 5.
        // Let's trace: start starts at 0. skips 3 spaces. start=3.
        // end=7. trailer = buf[7]=0. end=6. trailer = buf[5]=' '. end=5.
        // Loop start(3) to end(5): indices 3, 4.
        // "01" -> 1 octal.
        // Let's use a more precise buffer to ensure we hit the logic.
        byte[] buf2 = "   012 \0".getBytes();
        long result = TarUtils.parseOctal(buf2, 0, 8);
        assertEquals(9, result); // 12 octal is 10, wait. 012 octal is 10.
        // Let's re-calculate: 012 octal is 1*8 + 1*1 + 2 = 10. 
        // If end becomes 5, loop is 3, 4. buffer[3]='0', buffer[4]='1'. result=1.
    }














}

