package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen0Test {

















    @Test
    public void testParseOctal_ComplexTrailing() {
        // Test the "May have additional NUL or space" logic
        // buffer[end-1] check
        byte[] buffer = "012  \0".getBytes(); 
        // offset 0, length 6. end=6.
        // buffer[6] is '\0'. end becomes 5.
        // buffer[5] is ' '. end becomes 4.
        // start is 0. loop 0 to 4. indices 0,1,2,3.
        // "012 " -> index 3 is ' '. This should trigger InvalidDigit because ' ' < '0'.
        // Actually, the code checks if currentByte < '0'. ' ' is 32, '0' is 48.
        // So "012 " is invalid if the loop includes the space.

        // Let's try: "012\0 "
        byte[] buffer2 = "012\0 \0".getBytes();
        // len 6. end=6. buf[6]=0. end=5. buf[5]=' '. end=4.
        // start=0. end=4. indices 0,1,2,3.
        // buf[0]=0, buf[1]=1, buf[2]=2, buf[3]=0.
        // result = 0120 octal = 80 decimal.
        long result = TarUtils.parseOctal(buffer2, 0, 6);
        assertEquals(80L, result);
    }


}

